create or replace function powerhouse_ops.reconcile_cron_failures(p_since interval default interval '30 minutes',p_limit integer default 100) returns integer language plpgsql security invoker set search_path=pg_catalog,powerhouse_ops,cron as $f$ declare r record;v_count integer:=0; begin if p_since>interval '24 hours' or p_since<=interval '0 seconds' then raise exception 'invalid lookback';end if; for r in select runid,jobid,start_time,return_message from (select runid,jobid,status,start_time,return_message from cron.job_run_details order by runid desc limit 1000) recent where start_time>=now()-p_since and jobid in(46,116,138,171) and status='failed' order by runid desc limit least(greatest(p_limit,1),200) loop perform powerhouse_ops.enqueue('cron_failure_review',r.jobid::text||':'||r.runid::text,jsonb_build_object('jobid',r.jobid,'runid',r.runid,'start_time',r.start_time,'failure',left(coalesce(r.return_message,''),500),'replay_allowed',false));v_count:=v_count+1;end loop;return v_count;end $f$;
